/*——————输入框美化——————*/

#send_form {
  display: flex;
  flex-direction: column;
  width: 98%;
  max-width: 1190px;
  margin: 0px auto;
  /* 新增底部留白控制 */
  margin-bottom: 20px; /* 调整此值控制留白大小 */
  padding: 5px 20px;
  border-radius: 10px;
  position: relative;
  overflow: hidden;



  /* 古风夜间主题背景 */
  background-color: rgba(27, 36, 66, 0.85); /* 主背景色1B2442(深蓝) 85%透明度 */
  background-image: url('https://i.postimg.cc/PJq92w6Z/Image-2805383171683367.png'); 
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;

  /* 三层古风描边效果 */
  box-shadow: 
    0 0 0 1px #1B2442,          /* 第一层：金色描边(增强贵气感) */
    0 0 0 3px #1B2442,           /* 第二层：深蓝描边(主色调轮廓) */
    0 0 0 5px #1B2442,           /* 第三层：金色描边(强化层次) */
    inset 1px 1px 4px rgba(0, 0, 0, 0.5), /* 左上内陷阴影(增强立体感) */
    4px 4px 12px rgba(0, 0, 0, 0.6); /* 右下阴影(增强深度效果) */

  transition: all 0.4s ease;
}

/* 输入框 - 古风夜间模式 */
#send_form > input[type="text"],
#send_form > .image-url-container > input {
  background: rgba(27, 36, 66, 0.7); /* 深蓝半透明背景 */
  color: #FFF5DB;                   /* 米白色文字(提高可读性) */
  border: 1px solid #1B2442;        /* 金色边框(典雅分隔) */
  border-radius: 0px;               
  padding: 12px 15px;
  transition: all 0.3s ease;
  box-shadow: 
    inset 2px 2px 5px rgba(0, 0, 0, 0.4), /* 内陷阴影(强化凹陷感) */
    1px 1px 3px rgba(212, 175, 55, 0.3); /* 右下金色微光(立体效果) */
}

/* 聚焦状态 - 古风激活效果 */
#send_form > input[type="text"]:focus,
#send_form > .image-url-container > input:focus {
  border-color: #FFD700;          /* 亮金色焦点边框 */
  background: rgba(27, 36, 66, 0.9); /* 加深背景突出焦点 */
  outline: none;
  box-shadow: 
    inset 2px 2px 5px rgba(0, 0, 0, 0.4),
    0 0 8px rgba(255, 215, 0, 0.5); /* 金色光晕效果 */
}

/* 按钮 - 古风主题 */
#send_form > .button-container > button {
  border: 2px solid #D4AF37;      /* 金色边框 */
  background: rgba(27, 36, 66, 0.5); /* 深蓝半透明背景 */
  color: #FFF5DB;                 /* 米白色文字 */
  border-radius: 0px;             
  padding: 10px 18px;
  font-weight: 500;
  transition: all 0.3s ease;
  letter-spacing: 1px;
  box-shadow: 
    inset 1px 1px 2px rgba(212, 175, 55, 0.4), /* 金色内高光 */
    2px 2px 5px rgba(0, 0, 0, 0.5); /* 右下阴影 */
}

/* 按钮悬停 - 古风增强 */
#send_form > .button-container > button:hover {
  background: rgba(212, 175, 55, 0.2); /* 金色悬停效果 */
  transform: translateY(-2px);
  box-shadow: 
    inset 1px 1px 3px rgba(212, 175, 55, 0.6),
    3px 3px 10px rgba(0, 0, 0, 0.7); /* 强化阴影 */
}

/* 整体悬停 - 古风效果 */
#send_form:hover {
  box-shadow: 
    0 0 0 1px #1B2442,
    0 0 0 3px #FFF5DB,
    0 0 0 5px #1B2442,
    inset 1px 1px 5px rgba(0, 0, 0, 0.6),
    6px 6px 18px rgba(0, 0, 0, 0.8); /* 强化右下阴影 */
  transform: translateY(-3px);
  background-color: rgba(27, 36, 66, 0.95); /* 加深背景 */
}

/* 日间模式-古风适配 */
@media (prefers-color-scheme: light) {
  #send_form {
    background-color: rgba(255, 245, 219, 0.8); /* 米白背景(FFF5DB) */
    box-shadow: 
      0 0 0 1px #1B2442,          /* 深蓝描边 */
      0 0 0 3px #FFF5DB,           /* 金色描边 */
      0 0 0 5px #1B2442,           /* 深蓝描边 */
      inset 2px 2px 5px rgba(0, 0, 0, 0.15),
      4px 4px 10px rgba(0, 0, 0, 0.2);
  }

  #send_form > input[type="text"],
  #send_form > .image-url-container > input {
    background: rgba(255, 245, 219, 0.7); /* 米白背景 */
    color: #1B2442;                   /* 深蓝文字 */
    border: 1px solid #1B2442;        /* 深蓝边框 */
    box-shadow: 
      inset 2px 2px 4px rgba(0, 0, 0, 0.1),
      1px 1px 3px rgba(27, 36, 66, 0.2); /* 深蓝微光 */
  }

  /* 日间模式聚焦效果 */
  #send_form > input[type="text"]:focus,
  #send_form > .image-url-container > input:focus {
    border-color: #1B2442;
    box-shadow: 0 0 8px rgba(27, 36, 66, 0.4);
  }

  #send_form:hover {
    background-color: rgba(255, 245, 219, 0.9);
  }

  /* 日间按钮样式 */
  #send_form > .button-container > button {
    border: 2px solid #1B2442;
    color: #1B2442;
    box-shadow: 
      inset 1px 1px 2px rgba(27, 36, 66, 0.3),
      2px 2px 4px rgba(0, 0, 0, 0.2);
  }
}
/*——————复选——————*/
.title::after {
  background: linear-gradient(to right, 
    transparent, 
    #A89D8A 40%,  /* 灰米色 - 夜间模式下的标题装饰线 */
    #C1B0A7,      /* 浅陶土色 - 辅助过渡色 */
    transparent
  );
  box-shadow: none; /* 移除多余阴影 */
}

/* 复选框基底 - 深蓝紫夜色 */
input[type='checkbox'] {
  background: #2A3B4D; /* 深蓝灰基底（接近1B2442） */
  box-shadow: 
    inset 2px 2px 4px rgba(0, 0, 0, 0.5),  /* 左上角内陷阴影 */
    2px 2px 4px rgba(0, 0, 0, 0.4),        /* 右下角投影 */
    0 0 0 1px #1B2442,                     /* 第一层深蓝紫描边 */
    0 0 0 2px #FFF5DB,                     /* 第二层米白描边 */
    0 0 0 3px #1B2442;                     /* 第三层深蓝紫描边 */
}

/* 悬停状态 - 蓝紫色加深 */
input[type='checkbox']:hover {
  background: #32465A; /* 加深的蓝紫色 */
  box-shadow: 
    inset -2px -2px 4px rgba(0, 0, 0, 0.6), /* 右下角内陷阴影 */
    3px 3px 5px rgba(0, 0, 0, 0.5),         /* 加强右下投影 */
    0 0 0 1px #1B2442,                      /* 保持三层描边 */
    0 0 0 2px #FFF5DB,
    0 0 0 3px #1B2442;
}

/* 选中状态 - 米白基底 */
input[type='checkbox']:checked {
  background: #FFF5DB; /* 米白色基底 */
  box-shadow: 
    inset -2px -2px 4px rgba(0, 0, 0, 0.3), /* 右下角浅内陷 */
    2px 2px 4px rgba(0, 0, 0, 0.3),         /* 柔和右下投影 */
    0 0 0 1px #1B2442,                      /* 三层描边保持 */
    0 0 0 2px #FFF5DB,
    0 0 0 3px #1B2442;
}

/* 梅花图标 - 深蓝紫色 */
input[type='checkbox']:checked::after {
  content: '◈';
  font-size: 1.7em;
  position: absolute;
  top: 40%;
  left: 50%;
  transform: translate(-50%, -50%);
  color: #1B2442; /* 深蓝紫色图标 */
}

/* 确保原生勾选隐藏 */
input[type="checkbox"]::before {
  content: none !important;
}

/*——————文字效果美化——————*/
/* === 背景蒙版 - 千古风流主题 === */
body {
  background-color: #1B2442 !important;  /* 主背景：深邃夜空蓝 */
  background-image: 
    radial-gradient(circle at 1px 1px, rgba(255,245,219,0.05) 1px, transparent 0),
    radial-gradient(circle at 1px 1px, rgba(255,245,219,0.05) 1px, transparent 0);
  background-size: 10px 10px;
  background-position: 0 0, 5px 5px;  /* 双图层星点纹理：模拟夜空星光 */
}

/* === 单独修改设置页面文字颜色 === */
small {
    color: #FFF5DB; /* 古卷米白色文字 */
    opacity: 0.9;
}

/* === 主容器 - 古籍卷轴 === */
background: #232D52 !important;  /* 深蓝卷轴底色：比背景稍亮 */
border-radius: 12px !important;
box-shadow: 
  inset -3px -3px 6px rgba(0,0,0,0.4),  /* 左上角内陷阴影：卷轴凹陷 */
  0 0 0 1px #1B2442,                     /* 第一层描边：夜空深蓝 */
  0 0 0 2px #FFF5DB,                     /* 第二层描边：古籍米金 */
  0 0 0 3px #1B2442,                     /* 第三层描边：夜空深蓝 */
  5px 5px 15px rgba(0,0,0,0.6);         /* 右下角阴影：立体悬浮感 */

/* === 小文本 - 古籍批注 === */
small {
  color: #C9BFA5 !important;   /* 古铜色：陈旧墨迹 */
  opacity: 0.7;
}

/* === 代码块 - 秘籍符文 === */
code, pre {
  color: #E8DCC2 !important;   /* 羊皮纸淡黄色符文 */
  font-family: 'SimSun', '宋体', serif !important;
  border-radius: 4px !important;
  background: 
    linear-gradient(145deg, #1A223F, #252F4D),  /* 深蓝渐变：古卷底色 */
    url('https://i.postimg.cc/PJq92w6Z/Image-2805383171683367.png') !important;
  background-size: 100%, 15px 15px;
  background-blend-mode: overlay;
}
code {
  box-shadow: 
    inset -2px 2px 4px rgba(0,0,0,0.4),
    inset -1px -1px 4px rgba(255,245,219,0.2); /* 内凹雕版效果 */
  padding: 0.2em 0.5em !important;
}

pre {
  padding: 1em !important;
  overflow: auto !important;
}

/* === 引用气泡 - 江湖密语 === */
.mes_text q {
  background: #1B2442 !important;     /* 深蓝靛色：密信底色 */
  border-radius: 0px;
  box-shadow: 
    inset 0 1px 2px rgba(0,0,0,0.3),  /* 顶部内阴影：卷轴分隔 */
    0 0 0 2px #1B2442;                /* 深蓝描边：密信边框 */
}

/* === 区块渐变 - 真气流转 === */
blockquote::after {
  background: linear-gradient(to bottom, 
    rgba(26, 34, 63, 0.5) 0%,        /* 深蓝晕染 */
    rgba(43, 52, 91, 0) 100%);       /* 渐变透明 */
}

/* === 引用区块 - 武林箴言 === */
.mes_text blockquote, .mes_reasoning blockquote {
  border-left: 3px solid #C9BFA5;    /* 古铜左侧边框：陈旧金属 */
  padding-left: 15px;
  background-color: #252F4D;         /* 靛蓝背景：古卷内页 */
  color: #E8DCC2;                   /* 羊皮纸色文字 */
  border-radius: 0 6px 6px 0;
  box-shadow: inset 3px 0 5px -3px rgba(0,0,0,0.3); /* 左侧内阴影 */
}

/* === 色系变量 - 武林主题 === */
:root {  
  --SmartThemeQuoteColor: #C9BFA5; /* 主色调：古铜色 */
}

/* === 链接 - 经脉连接 === */
a {
  color: #A89E86;               /* 古铜褪色 */
  border-bottom: 1px solid #5A6585; /* 深蓝灰下划线 */
}
a:hover {
  border-bottom: 2px solid #C9BFA5; /* 悬停古铜色 */
  color: #E8DCC2;
}

