/* 滚动条 - 古风夜间主题 */
::-webkit-scrollbar {
  width: 0px;
  height: 8px; 
}
::-webkit-scrollbar-track {
  background: #1B2442;             /* 深蓝轨道 */
}
::-webkit-scrollbar-thumb {
  background: #2A3A5A;             /* 浅蓝滑块 */
  border-radius: 4px;
  border: 1px solid #FFEDC8;       /* 米色边框 */
}
::-webkit-scrollbar-thumb:hover {
  background: #35466A;             /* 悬停加深 */
}

/* 文本框 - 三层描边+背景图 */
textarea {
  background: #1B2442;             /* 深蓝背景 */
  color: #FFF5DB;                  /* 米色文字 */
  border: 1px solid #1B2442;       /* 第一层深蓝描边 */
  border-radius: 6px;
  box-shadow: 
    inset 1px 1px 0px #2A3A5A,    /* 左上内浅蓝辉光 */
    inset 2px 2px 2px #0E1629,    /* 右下内深蓝阴影 */
    0 0 0 1px #FFF5DB,            /* 第二层米色描边 */
