  background-blend-mode: overlay;  /* 背景混合模式 */
}

textarea:focus {
  box-shadow: 
    inset 1px 1px 0px #35466A,
    inset -1px -1px 0px #121B33,
    0 0 0 1px #FFEDC8,
    0 0 8px rgba(255, 245, 219, 0.3); /* 聚焦米色光晕 */
}

textarea::placeholder {
  color: #7A86A0;                  /* 灰蓝色占位符 */
}

